-- Source: supabase/security.sql
-- UPC authorization and RPC layer. Apply after base-schema.sql.
-- Public review reads go through a safe view; base-table SELECT is limited to the
-- author and active reviewers, so user IDs and moderation fields never leak.

CREATE SCHEMA IF NOT EXISTS private;
REVOKE ALL ON SCHEMA private FROM PUBLIC;
GRANT USAGE ON SCHEMA private TO authenticated;

CREATE OR REPLACE FUNCTION private.upc_admin_role() RETURNS TEXT
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT a.role
  FROM public.admin_users a
  JOIN auth.users u ON lower(u.email) = lower(a.email)
  WHERE u.id = auth.uid()
    AND u.email_confirmed_at IS NOT NULL
    AND a.is_active
    AND a.role IN ('super_admin', 'admin', 'moderator')
  LIMIT 1
$$;
REVOKE ALL ON FUNCTION private.upc_admin_role() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.upc_admin_role() TO authenticated;

CREATE OR REPLACE FUNCTION public.get_my_admin_status() RETURNS JSONB
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$
  SELECT coalesce((
    SELECT jsonb_build_object('is_admin', true, 'role', a.role, 'nickname', a.nickname)
    FROM public.admin_users a
    JOIN auth.users u ON lower(u.email) = lower(a.email)
    WHERE u.id = auth.uid()
      AND u.email_confirmed_at IS NOT NULL
      AND a.is_active
      AND a.role IN ('super_admin', 'admin', 'moderator')
    LIMIT 1
  ), jsonb_build_object('is_admin', false))
$$;

-- Replace all historical policies: permissive policies combine with OR.
DO $$
DECLARE v RECORD; tbl TEXT;
BEGIN
  FOR v IN SELECT tablename, policyname FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename IN ('teachers','reviews','review_likes','user_profiles','point_transactions',
                        'admin_users','courses','colleges','terms','course_offerings','point_rules',
                        'import_batches')
  LOOP
    EXECUTE format('DROP POLICY %I ON public.%I', v.policyname, v.tablename);
  END LOOP;

  FOREACH tbl IN ARRAY ARRAY['teachers','reviews','review_likes','user_profiles','point_transactions',
                             'admin_users','courses','colleges','terms','course_offerings','point_rules',
                             'import_batches'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', tbl);
    EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC, anon, authenticated', tbl);
  END LOOP;
END $$;

GRANT SELECT ON public.teachers, public.courses, public.colleges, public.terms,
  public.course_offerings, public.point_rules TO anon, authenticated;
CREATE POLICY catalog_read ON public.teachers FOR SELECT USING (true);
CREATE POLICY catalog_read ON public.courses FOR SELECT USING (true);
CREATE POLICY catalog_read ON public.colleges FOR SELECT USING (true);
CREATE POLICY catalog_read ON public.terms FOR SELECT USING (true);
CREATE POLICY catalog_read ON public.course_offerings FOR SELECT USING (true);
CREATE POLICY catalog_read ON public.point_rules FOR SELECT USING (true);

-- Safe public review projection. The view runs with its owner's privileges and
-- deliberately exposes only approved, non-identifying fields. It does not expose
-- user_id, reviewer_id, reject_reason or reviewed_at.
CREATE OR REPLACE VIEW public.review_feed AS
SELECT
  r.id, r.teacher_id, r.course_id, r.term_id, r.year_term,
  r.attendance_strictness, r.grading_leniency, r.effort_matters,
  r.workload_difficulty, r.approachability, r.teaching_quality,
  r.comment, r.author_nickname, r.is_historical_migrated,
  r.status, r.created_at, r.likes, r.rating_version,
  c.name AS course_name,
  t.name AS teacher_name
FROM public.reviews r
LEFT JOIN public.courses c ON c.id = r.course_id
LEFT JOIN public.teachers t ON t.id = r.teacher_id
WHERE r.status = 'approved';
REVOKE ALL ON public.review_feed FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.review_feed TO anon, authenticated;

-- Authors and active reviewers may read base rows; everyone else uses the view.
GRANT SELECT ON public.reviews TO authenticated;
CREATE POLICY reviews_member_read ON public.reviews FOR SELECT TO authenticated
  USING (user_id = auth.uid()::text OR private.upc_admin_role() IS NOT NULL);

GRANT INSERT (id, teacher_id, course_id, term_id, year_term,
  attendance_strictness, grading_leniency, effort_matters, workload_difficulty,
  approachability, teaching_quality, comment, author_nickname, user_id,
  is_historical_migrated, status, created_at, likes, rating_version)
  ON public.reviews TO authenticated;
GRANT UPDATE (course_id, term_id, year_term, attendance_strictness, grading_leniency,
  effort_matters, workload_difficulty, approachability, teaching_quality, comment,
  status, reject_reason, rating_version)
  ON public.reviews TO authenticated;
GRANT DELETE ON public.reviews TO authenticated;

CREATE POLICY reviews_submit ON public.reviews FOR INSERT TO authenticated
  WITH CHECK (
    user_id = auth.uid()::text
    AND status = 'pending'
    AND NOT is_historical_migrated
    AND likes = 0
    AND reviewer_id IS NULL
    AND reviewed_at IS NULL
    AND reject_reason IS NULL
    AND rating_version = 2
    AND EXISTS (
      SELECT 1 FROM public.course_offerings o
      WHERE o.teacher_id = reviews.teacher_id
        AND o.course_id = reviews.course_id
        AND o.term_id = reviews.term_id
    )
  );
CREATE POLICY reviews_author_edit ON public.reviews FOR UPDATE TO authenticated
  USING (user_id = auth.uid()::text AND status IN ('pending', 'rejected'))
  WITH CHECK (
    user_id = auth.uid()::text
    AND status = 'pending'
    AND rating_version = 2
    AND EXISTS (
      SELECT 1 FROM public.course_offerings o
      WHERE o.teacher_id = reviews.teacher_id
        AND o.course_id = reviews.course_id
        AND o.term_id = reviews.term_id
    )
  );
CREATE POLICY reviews_delete ON public.reviews FOR DELETE TO authenticated
  USING (private.upc_admin_role() IS NOT NULL OR (user_id = auth.uid()::text AND status IN ('pending', 'rejected')));

GRANT SELECT ON public.user_profiles, public.point_transactions TO authenticated;
CREATE POLICY points_owner_read ON public.user_profiles FOR SELECT TO authenticated
  USING (id = auth.uid()::text);
CREATE POLICY ledger_owner_read ON public.point_transactions FOR SELECT TO authenticated
  USING (user_id = auth.uid()::text);

GRANT SELECT ON public.review_likes TO authenticated;
CREATE POLICY likes_read_own ON public.review_likes FOR SELECT TO authenticated
  USING (user_id = auth.uid());

GRANT SELECT, INSERT, UPDATE, DELETE ON public.admin_users TO authenticated;
CREATE POLICY admin_members_read ON public.admin_users FOR SELECT TO authenticated
  USING (private.upc_admin_role() = 'super_admin');
CREATE POLICY admin_members_manage ON public.admin_users FOR ALL TO authenticated
  USING (private.upc_admin_role() = 'super_admin')
  WITH CHECK (private.upc_admin_role() = 'super_admin' AND role IN ('super_admin', 'admin', 'moderator'));

-- No import_batches policy: the table is service-role only.

-- Durable reward marker survives review deletion and is never exposed.
CREATE TABLE IF NOT EXISTS private.upc_review_rewards (
  review_id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  awarded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
REVOKE ALL ON private.upc_review_rewards FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION private.upc_ensure_profile(p_user_id TEXT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE inserted_id TEXT; initial_points INTEGER;
BEGIN
  IF EXISTS (SELECT 1 FROM public.user_profiles WHERE id = p_user_id) THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id::text = p_user_id) THEN
    RAISE EXCEPTION 'Unknown authenticated user';
  END IF;
  SELECT points_delta INTO initial_points
  FROM public.point_rules
  WHERE action_code = 'new_user_welcome' AND is_active;
  IF initial_points IS NULL OR initial_points < 0 THEN
    RAISE EXCEPTION '注册积分规则不可用';
  END IF;
  INSERT INTO public.user_profiles (id, points)
  VALUES (p_user_id, initial_points)
  ON CONFLICT (id) DO NOTHING
  RETURNING id INTO inserted_id;
  IF inserted_id IS NOT NULL THEN
    INSERT INTO public.point_transactions (id, user_id, action, action_code, amount, balance_after)
    VALUES (gen_random_uuid()::text, p_user_id, '新用户注册赠送', 'new_user_welcome', initial_points, initial_points);
  END IF;
END $$;
REVOKE ALL ON FUNCTION private.upc_ensure_profile(TEXT) FROM PUBLIC, anon, authenticated;

DROP FUNCTION IF EXISTS public.handle_daily_checkin();
CREATE FUNCTION public.handle_daily_checkin()
RETURNS TABLE(points INTEGER, already_checked_in BOOLEAN)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  uid TEXT := auth.uid()::text;
  bal INTEGER;
  last_day DATE;
  reward INTEGER;
  today DATE := (now() AT TIME ZONE 'Asia/Shanghai')::date;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION '请先登录'; END IF;
  PERFORM private.upc_ensure_profile(uid);
  SELECT p.points, p.last_checkin_date INTO bal, last_day
  FROM public.user_profiles p WHERE p.id = uid FOR UPDATE;
  IF last_day = today THEN
    RETURN QUERY SELECT bal, true;
    RETURN;
  END IF;
  SELECT pr.points_delta INTO reward
  FROM public.point_rules pr
  WHERE pr.action_code = 'daily_checkin' AND pr.is_active;
  IF reward IS NULL OR reward <= 0 THEN RAISE EXCEPTION '签到积分规则不可用'; END IF;
  UPDATE public.user_profiles p
  SET points = p.points + reward, last_checkin_date = today
  WHERE id = uid
  RETURNING p.points INTO bal;
  INSERT INTO public.point_transactions (id, user_id, action, action_code, amount, balance_after)
  VALUES (gen_random_uuid()::text, uid, '每日签到奖励', 'daily_checkin', reward, bal);
  RETURN QUERY SELECT bal, false;
END $$;

-- Generic rule-based deduction. There is no hard-coded AI/feature allow-list:
-- only active negative rules can be spent, and phase-one has no active spend rule.
CREATE OR REPLACE FUNCTION public.spend_points(p_action_code TEXT, p_note TEXT DEFAULT NULL)
RETURNS INTEGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid TEXT := auth.uid()::text; bal INTEGER; cost INTEGER;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION '请先登录'; END IF;
  SELECT pr.points_delta INTO cost
  FROM public.point_rules pr
  WHERE pr.action_code = p_action_code AND pr.is_active;
  IF cost IS NULL OR cost >= 0 THEN RAISE EXCEPTION '积分消费规则不可用'; END IF;
  PERFORM private.upc_ensure_profile(uid);
  SELECT points INTO bal FROM public.user_profiles WHERE id = uid FOR UPDATE;
  IF bal + cost < 0 THEN RAISE EXCEPTION 'insufficient points: 积分不足'; END IF;
  UPDATE public.user_profiles p SET points = p.points + cost WHERE id = uid RETURNING p.points INTO bal;
  INSERT INTO public.point_transactions (id, user_id, action, action_code, amount, balance_after)
  VALUES (gen_random_uuid()::text, uid, coalesce(p_note, '积分消费'), p_action_code, cost, bal);
  RETURN bal;
END $$;

DROP FUNCTION IF EXISTS public.approve_review(TEXT);
CREATE FUNCTION public.approve_review(p_review_id TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  rev public.reviews%ROWTYPE;
  bal INTEGER;
  inserted_review TEXT;
  reviewer UUID;
  reward INTEGER;
BEGIN
  IF auth.uid() IS NULL OR private.upc_admin_role() IS NULL THEN RAISE EXCEPTION '无审核权限'; END IF;
  SELECT * INTO rev FROM public.reviews WHERE id = p_review_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'message', '评价不存在'); END IF;
  IF rev.status = 'approved' THEN
    RETURN jsonb_build_object('success', true, 'points_awarded', false, 'message', '评价已审核通过');
  END IF;
  IF rev.status NOT IN ('pending', 'rejected') OR rev.status IS NULL THEN
    RAISE EXCEPTION '无效的评价状态';
  END IF;
  SELECT a.id INTO reviewer
  FROM public.admin_users a
  JOIN auth.users u ON lower(u.email) = lower(a.email)
  WHERE u.id = auth.uid() AND a.is_active;
  UPDATE public.reviews
  SET status = 'approved', reject_reason = NULL, reviewer_id = reviewer, reviewed_at = now()
  WHERE id = p_review_id;
  IF NOT coalesce(rev.is_historical_migrated, false)
     AND EXISTS (SELECT 1 FROM auth.users WHERE id::text = rev.user_id) THEN
    PERFORM private.upc_ensure_profile(rev.user_id);
    PERFORM 1 FROM public.user_profiles WHERE id = rev.user_id FOR UPDATE;
    INSERT INTO private.upc_review_rewards (review_id, user_id)
    VALUES (rev.id, rev.user_id)
    ON CONFLICT DO NOTHING
    RETURNING review_id INTO inserted_review;
    IF inserted_review IS NOT NULL THEN
      SELECT pr.points_delta INTO reward
      FROM public.point_rules pr
      WHERE pr.action_code = 'review_approved' AND pr.is_active;
      IF reward IS NULL OR reward <= 0 THEN RAISE EXCEPTION '评价奖励规则不可用'; END IF;
      UPDATE public.user_profiles p
      SET points = p.points + reward
      WHERE id = rev.user_id
      RETURNING p.points INTO bal;
      INSERT INTO public.point_transactions
        (id, user_id, action, action_code, amount, balance_after, related_review_id)
      VALUES (gen_random_uuid()::text, rev.user_id, '撰写教师评价审核通过',
        'review_approved', reward, bal, rev.id);
    END IF;
  END IF;
  RETURN jsonb_build_object('success', true, 'points_awarded', inserted_review IS NOT NULL,
    'message', '评价已通过审核');
END $$;

DROP FUNCTION IF EXISTS public.reject_review(TEXT, TEXT);
CREATE FUNCTION public.reject_review(p_review_id TEXT, p_reason TEXT) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE reviewer UUID;
BEGIN
  IF auth.uid() IS NULL OR private.upc_admin_role() IS NULL THEN RAISE EXCEPTION '无审核权限'; END IF;
  IF nullif(trim(p_reason), '') IS NULL THEN RAISE EXCEPTION '请填写驳回原因'; END IF;
  SELECT a.id INTO reviewer
  FROM public.admin_users a
  JOIN auth.users u ON lower(u.email) = lower(a.email)
  WHERE u.id = auth.uid() AND a.is_active;
  UPDATE public.reviews
  SET status = 'rejected', reject_reason = p_reason, reviewer_id = reviewer, reviewed_at = now()
  WHERE id = p_review_id;
  RETURN jsonb_build_object('success', FOUND, 'message',
    CASE WHEN FOUND THEN '评价已被驳回' ELSE '评价不存在' END);
END $$;

-- Revoke default PUBLIC execution, including any historical overloads.
DO $$
DECLARE v RECORD;
BEGIN
  FOR v IN SELECT p.oid::regprocedure AS signature
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN ('get_my_admin_status','handle_daily_checkin','spend_points','approve_review','reject_review')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated', v.signature);
  END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION public.get_my_admin_status(), public.handle_daily_checkin(),
  public.spend_points(TEXT, TEXT), public.approve_review(TEXT), public.reject_review(TEXT, TEXT)
  TO authenticated;

DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT USAGE ON SCHEMA public TO service_role;
    GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO service_role;
    GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
    GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO service_role;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


-- Source: supabase/fresh-hooks.sql
-- UPC triggers and like RPC. Apply after security.sql.

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  PERFORM private.upc_ensure_profile(NEW.id::text);
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

CREATE OR REPLACE FUNCTION private.upc_touch_teacher() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.upc_touch_teacher() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS teachers_touch_updated_at ON public.teachers;
CREATE TRIGGER teachers_touch_updated_at
  BEFORE UPDATE ON public.teachers
  FOR EACH ROW EXECUTE FUNCTION private.upc_touch_teacher();

-- Recompute every dimension from approved reviews. With zero approved reviews the
-- averages are NULL, which clears stale scores instead of keeping an old value.
CREATE OR REPLACE FUNCTION public.recalc_teacher_scores() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE target_teacher_id TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    target_teacher_id := OLD.teacher_id;
  ELSE
    target_teacher_id := NEW.teacher_id;
  END IF;

  UPDATE public.teachers t
  SET
    review_count = a.review_count,
    attendance_strictness = a.attendance_strictness,
    grading_leniency = a.grading_leniency,
    effort_matters = a.effort_matters,
    workload_difficulty = a.workload_difficulty,
    approachability = a.approachability,
    teaching_quality = a.teaching_quality,
    overall_score = a.overall_score,
    updated_at = now()
  FROM (
    SELECT
      count(*)::int AS review_count,
      avg(r.attendance_strictness) AS attendance_strictness,
      avg(r.grading_leniency) AS grading_leniency,
      avg(r.effort_matters) AS effort_matters,
      avg(r.workload_difficulty) AS workload_difficulty,
      avg(r.approachability) AS approachability,
      avg(r.teaching_quality) AS teaching_quality,
      avg(
        (coalesce(r.attendance_strictness, 0) + coalesce(r.grading_leniency, 0) +
         coalesce(r.effort_matters, 0) + coalesce(r.workload_difficulty, 0) +
         coalesce(r.approachability, 0) + coalesce(r.teaching_quality, 0)) /
        nullif(
          (r.attendance_strictness IS NOT NULL)::int + (r.grading_leniency IS NOT NULL)::int +
          (r.effort_matters IS NOT NULL)::int + (r.workload_difficulty IS NOT NULL)::int +
          (r.approachability IS NOT NULL)::int + (r.teaching_quality IS NOT NULL)::int,
          0
        )
      ) AS overall_score
    FROM public.reviews r
    WHERE r.teacher_id = target_teacher_id
      AND r.status = 'approved'
  ) a
  WHERE t.id = target_teacher_id;

  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION public.recalc_teacher_scores() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS trg_recalc_teacher_scores ON public.reviews;
CREATE TRIGGER trg_recalc_teacher_scores
  AFTER INSERT OR DELETE OR UPDATE OF status, attendance_strictness, grading_leniency,
    effort_matters, workload_difficulty, approachability, teaching_quality
  ON public.reviews
  FOR EACH ROW EXECUTE FUNCTION public.recalc_teacher_scores();

-- Reject v1 clients and out-of-range values before they can be stored.
CREATE OR REPLACE FUNCTION private.upc_check_rating_version() RETURNS TRIGGER
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
  IF NEW.rating_version IS DISTINCT FROM 2 THEN
    RAISE EXCEPTION '评分规则已更新，请刷新页面后重试';
  END IF;
  IF current_user IN ('authenticated', 'anon')
     AND coalesce(nullif(current_setting('request.headers', true), '')::jsonb->>'x-rating-version', '') <> '2' THEN
    RAISE EXCEPTION '评分规则已更新，请刷新页面后重试';
  END IF;
  IF NEW.is_historical_migrated = false THEN
    -- New submissions are six required decimal scores in [4.0, 5.0]. The
    -- columns are unconstrained NUMERIC so 4.15 reaches this check intact.
    IF EXISTS (
      SELECT 1 FROM unnest(ARRAY[
        NEW.attendance_strictness, NEW.grading_leniency, NEW.effort_matters,
        NEW.workload_difficulty, NEW.approachability, NEW.teaching_quality
      ]) s WHERE s IS NULL
    ) THEN
      RAISE EXCEPTION '六项评分均为必填';
    END IF;
    IF EXISTS (
      SELECT 1 FROM unnest(ARRAY[
        NEW.attendance_strictness, NEW.grading_leniency, NEW.effort_matters,
        NEW.workload_difficulty, NEW.approachability, NEW.teaching_quality
      ]) s
      WHERE s < 4 OR s > 5 OR s <> round(s, 1)
    ) THEN
      RAISE EXCEPTION '新提交评分须在 4.0 到 5.0 之间，最多一位小数';
    END IF;
  ELSIF EXISTS (
    SELECT 1 FROM unnest(ARRAY[
      NEW.attendance_strictness, NEW.grading_leniency, NEW.effort_matters,
      NEW.workload_difficulty, NEW.approachability, NEW.teaching_quality
    ]) s
    WHERE s IS NOT NULL AND NOT (s BETWEEN 1 AND 5)
  ) THEN
    RAISE EXCEPTION '历史评分必须在 1 到 5 分之间';
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION private.upc_check_rating_version() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS reviews_check_rating_version ON public.reviews;
CREATE TRIGGER reviews_check_rating_version
  BEFORE INSERT OR UPDATE OF rating_version, attendance_strictness, grading_leniency,
    effort_matters, workload_difficulty, approachability, teaching_quality
  ON public.reviews
  FOR EACH ROW EXECUTE FUNCTION private.upc_check_rating_version();

CREATE OR REPLACE FUNCTION private.upc_count_review_like() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.reviews SET likes = coalesce(likes, 0) + 1 WHERE id = NEW.review_id;
  ELSE
    UPDATE public.reviews
    SET likes = greatest(legacy_likes, coalesce(likes, 0) - 1)
    WHERE id = OLD.review_id;
  END IF;
  RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION private.upc_count_review_like() FROM PUBLIC, anon, authenticated;
DROP TRIGGER IF EXISTS review_likes_count ON public.review_likes;
CREATE TRIGGER review_likes_count
  AFTER INSERT OR DELETE ON public.review_likes
  FOR EACH ROW EXECUTE FUNCTION private.upc_count_review_like();

CREATE OR REPLACE FUNCTION public.set_review_like(p_review_id TEXT, p_liked BOOLEAN)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE uid UUID := auth.uid(); review_status TEXT; review_teacher_id TEXT; total INTEGER;
BEGIN
  IF uid IS NULL OR NOT EXISTS (SELECT 1 FROM auth.users WHERE id = uid) THEN
    RAISE EXCEPTION '请先登录后点赞';
  END IF;
  IF p_liked IS NULL THEN RAISE EXCEPTION '请明确点赞或取消点赞'; END IF;
  SELECT status, teacher_id INTO review_status, review_teacher_id
  FROM public.reviews WHERE id = p_review_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '评价不存在'; END IF;
  IF p_liked AND review_status IS DISTINCT FROM 'approved' THEN
    RAISE EXCEPTION '只能点赞已通过审核的评价';
  END IF;
  IF p_liked THEN
    INSERT INTO public.review_likes (review_id, user_id)
    VALUES (p_review_id, uid)
    ON CONFLICT DO NOTHING;
  ELSE
    DELETE FROM public.review_likes WHERE review_id = p_review_id AND user_id = uid;
  END IF;
  SELECT likes INTO total FROM public.reviews WHERE id = p_review_id;
  RETURN jsonb_build_object('likes', total, 'liked', p_liked, 'teacher_id', review_teacher_id);
END $$;
REVOKE ALL ON FUNCTION public.set_review_like(TEXT, BOOLEAN) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.set_review_like(TEXT, BOOLEAN) TO authenticated;

NOTIFY pgrst, 'reload schema';


-- Source: supabase/import-upc.sql
-- Atomic UPC data import. Executed with the service role only.
--
-- Contract:
--   * teachers are keyed by sourceId and stored as 'upc:<sourceId>';
--   * same-name teachers are never merged;
--   * courses are keyed by code when present, otherwise by (name, college);
--   * offerings require a term and are unique by teacher × course × term;
--   * a dry run executes the same writes in a subtransaction, then rolls back;
--     batch conflicts therefore fail the preflight exactly as the real import;
--   * any bad row aborts the whole call, so a partial batch is never committed.

CREATE OR REPLACE FUNCTION private.upc_import_dataset_apply(
  p_payload JSONB,
  p_checksum TEXT
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_term JSONB;
  v_teachers JSONB;
  v_teacher JSONB;
  v_course JSONB;
  v_dataset TEXT;
  v_source TEXT;
  v_term_code TEXT;
  v_term_name TEXT;
  v_term_current BOOLEAN;
  v_term_id UUID;
  v_existing_term_name TEXT;
  v_existing_term_current BOOLEAN;
  v_term_inserted INT := 0;
  v_term_updated INT := 0;
  v_term_skipped INT := 0;
  v_teacher_inserted INT := 0;
  v_teacher_updated INT := 0;
  v_teacher_skipped INT := 0;
  v_course_inserted INT := 0;
  v_course_updated INT := 0;
  v_course_skipped INT := 0;
  v_offering_inserted INT := 0;
  v_offering_skipped INT := 0;
  v_source_id TEXT;
  v_teacher_id TEXT;
  v_name TEXT;
  v_title TEXT;
  v_campus TEXT;
  v_college_code TEXT;
  v_college_id UUID;
  v_course_code TEXT;
  v_course_name TEXT;
  v_course_college_code TEXT;
  v_course_college_id UUID;
  v_course_id UUID;
  v_existing_course_name TEXT;
  v_existing_course_college UUID;
  v_same BOOLEAN;
  v_rows INT;
  v_summary JSONB;
BEGIN
  IF p_payload IS NULL OR jsonb_typeof(p_payload) <> 'object' THEN
    RAISE EXCEPTION '导入数据必须是 JSON 对象';
  END IF;
  IF coalesce(p_payload->>'schemaVersion', '') !~ '^[0-9]+$'
     OR (p_payload->>'schemaVersion')::int <> 1 THEN
    RAISE EXCEPTION '不支持的导入数据版本，只接受 schemaVersion=1';
  END IF;
  IF p_checksum IS NULL OR p_checksum !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION '缺少有效的 SHA-256 校验值';
  END IF;

  v_dataset := nullif(trim(p_payload->>'dataset'), '');
  v_source := nullif(trim(p_payload->>'source'), '');
  IF v_dataset IS NULL OR char_length(v_dataset) > 200 THEN
    RAISE EXCEPTION 'dataset 必填且不超过 200 字符';
  END IF;
  IF v_source IS NULL OR char_length(v_source) > 500 THEN
    RAISE EXCEPTION 'source 必填且不超过 500 字符（记录可核对的来源）';
  END IF;

  v_teachers := p_payload->'teachers';
  IF v_teachers IS NULL OR jsonb_typeof(v_teachers) <> 'array' OR jsonb_array_length(v_teachers) = 0 THEN
    RAISE EXCEPTION 'teachers 必须是非空数组';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM jsonb_array_elements(v_teachers) e
    GROUP BY nullif(trim(e->>'sourceId'), '')
    HAVING count(*) > 1 OR nullif(trim(e->>'sourceId'), '') IS NULL
  ) THEN
    RAISE EXCEPTION 'teachers 中存在空白或重复的 sourceId';
  END IF;

  v_term := p_payload->'term';
  IF v_term IS NOT NULL AND jsonb_typeof(v_term) = 'null' THEN
    v_term := NULL;
  END IF;
  IF v_term IS NOT NULL THEN
    IF jsonb_typeof(v_term) <> 'object' THEN
      RAISE EXCEPTION 'term 必须是对象或 null';
    END IF;
    v_term_code := nullif(trim(v_term->>'code'), '');
    v_term_name := nullif(trim(v_term->>'name'), '');
    IF v_term_code IS NULL OR v_term_name IS NULL THEN
      RAISE EXCEPTION 'term.code 与 term.name 均必填';
    END IF;
    v_term_current := coalesce((v_term->>'isCurrent')::boolean, false);

    SELECT id, year_term, is_current INTO v_term_id, v_existing_term_name, v_existing_term_current
    FROM public.terms WHERE code = v_term_code;

    IF v_term_id IS NULL THEN
      INSERT INTO public.terms (code, year_term, is_current)
      VALUES (v_term_code, v_term_name, false)
      RETURNING id INTO v_term_id;
      v_term_inserted := v_term_inserted + 1;
    ELSIF v_existing_term_name = v_term_name AND v_existing_term_current = v_term_current THEN
      v_term_skipped := v_term_skipped + 1;
    ELSE
      UPDATE public.terms
      SET year_term = v_term_name
      WHERE id = v_term_id;
      v_term_updated := v_term_updated + 1;
    END IF;

    IF v_term_current THEN
      UPDATE public.terms SET is_current = false
      WHERE is_current AND id IS DISTINCT FROM v_term_id;
      UPDATE public.terms SET is_current = true WHERE id = v_term_id;
    END IF;
  END IF;

  FOR v_teacher IN SELECT value FROM jsonb_array_elements(v_teachers) LOOP
    v_source_id := nullif(trim(v_teacher->>'sourceId'), '');
    v_name := nullif(trim(v_teacher->>'name'), '');
    v_title := nullif(trim(v_teacher->>'title'), '');
    v_campus := nullif(trim(v_teacher->>'campus'), '');
    v_college_code := nullif(trim(v_teacher->>'collegeCode'), '');

    IF v_source_id IS NULL OR char_length(v_source_id) > 120
       OR position('/' IN v_source_id) > 0 OR position(chr(92) IN v_source_id) > 0 THEN
      RAISE EXCEPTION '教师 sourceId 必填、不超过 120 字符且不能包含斜杠';
    END IF;
    IF v_name IS NULL OR char_length(v_name) > 80 THEN
      RAISE EXCEPTION '教师 % 的姓名必填且不超过 80 字符', v_source_id;
    END IF;
    IF v_title IS NOT NULL AND char_length(v_title) > 40 THEN
      RAISE EXCEPTION '教师 % 的职称超过 40 字符', v_source_id;
    END IF;
    IF v_campus IS NOT NULL AND v_campus NOT IN ('唐岛湾校区', '古镇口校区', '东营科教园区') THEN
      RAISE EXCEPTION '教师 % 的校区 % 不在 UPC 校区枚举中', v_source_id, v_campus;
    END IF;
    IF v_college_code IS NULL THEN
      RAISE EXCEPTION '教师 % 缺少 collegeCode', v_source_id;
    END IF;

    SELECT id INTO v_college_id FROM public.colleges WHERE code = v_college_code;
    IF v_college_id IS NULL THEN
      RAISE EXCEPTION '教师 % 的学院编码 % 不存在，请先导入学院字典', v_source_id, v_college_code;
    END IF;

    v_teacher_id := 'upc:' || v_source_id;
    IF NOT EXISTS (SELECT 1 FROM public.teachers WHERE id = v_teacher_id) THEN
      INSERT INTO public.teachers (id, source_id, name, title, college_id, campus, rating_version)
      VALUES (v_teacher_id, v_source_id, v_name, v_title, v_college_id, v_campus, 2);
      v_teacher_inserted := v_teacher_inserted + 1;
    ELSE
      SELECT (name = v_name
              AND title IS NOT DISTINCT FROM v_title
              AND college_id = v_college_id
              AND campus IS NOT DISTINCT FROM v_campus)
      INTO v_same
      FROM public.teachers WHERE id = v_teacher_id;

      IF v_same THEN
        v_teacher_skipped := v_teacher_skipped + 1;
      ELSE
        UPDATE public.teachers
        SET name = v_name, title = v_title, college_id = v_college_id, campus = v_campus
        WHERE id = v_teacher_id;
        v_teacher_updated := v_teacher_updated + 1;
      END IF;
    END IF;

    IF v_teacher ? 'courses' AND jsonb_typeof(v_teacher->'courses') <> 'array' THEN
      RAISE EXCEPTION '教师 % 的 courses 必须是数组', v_source_id;
    END IF;
    IF jsonb_array_length(coalesce(v_teacher->'courses', '[]'::jsonb)) > 0
       AND v_term IS NULL THEN
      RAISE EXCEPTION '教师 % 有课程但整批未提供 term', v_source_id;
    END IF;

    FOR v_course IN SELECT value FROM jsonb_array_elements(coalesce(v_teacher->'courses', '[]'::jsonb)) LOOP
      v_course_code := nullif(trim(v_course->>'code'), '');
      v_course_name := nullif(trim(v_course->>'name'), '');
      IF v_course_name IS NULL OR char_length(v_course_name) > 160 THEN
        RAISE EXCEPTION '教师 % 的课程名称必填且不超过 160 字符', v_source_id;
      END IF;
      IF v_course_code IS NOT NULL AND char_length(v_course_code) > 80 THEN
        RAISE EXCEPTION '教师 % 的课程代码超过 80 字符', v_source_id;
      END IF;

      -- The offering unit is separate from the teacher's HR college. It defaults
      -- to the teacher's college when not supplied.
      v_course_college_code := nullif(trim(v_course->>'collegeCode'), '');
      IF v_course_college_code IS NULL THEN
        v_course_college_id := v_college_id;
      ELSE
        SELECT id INTO v_course_college_id
        FROM public.colleges WHERE code = v_course_college_code;
        IF v_course_college_id IS NULL THEN
          RAISE EXCEPTION '教师 % 的课程 % 指定学院编码 % 不存在', v_source_id, v_course_name, v_course_college_code;
        END IF;
      END IF;

      v_course_id := NULL;
      v_existing_course_name := NULL;
      v_existing_course_college := NULL;

      IF v_course_code IS NOT NULL THEN
        SELECT id, name, college_id
        INTO v_course_id, v_existing_course_name, v_existing_course_college
        FROM public.courses WHERE code = v_course_code;

        IF v_course_id IS NOT NULL THEN
          IF v_existing_course_name IS DISTINCT FROM v_course_name THEN
            RAISE EXCEPTION '课程代码 % 已存在名称 %，与本次名称 % 冲突',
              v_course_code, v_existing_course_name, v_course_name;
          END IF;
          IF v_existing_course_college IS DISTINCT FROM v_course_college_id THEN
            RAISE EXCEPTION '课程代码 % 已归属其他学院，不能静默改归属', v_course_code;
          END IF;
          v_course_skipped := v_course_skipped + 1;
        ELSE
          -- Adopt a single uncoded course with the same name/college. If a coded
          -- same-name course also exists, the uncoded record is ambiguous.
          SELECT id INTO v_course_id
          FROM public.courses
          WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NULL
          LIMIT 1;

          IF v_course_id IS NOT NULL THEN
            IF EXISTS (
              SELECT 1 FROM public.courses
              WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NOT NULL
            ) THEN
              RAISE EXCEPTION '课程 % 同时存在有编码和无编码记录，无法安全采用编码 %',
                v_course_name, v_course_code;
            END IF;
            UPDATE public.courses SET code = v_course_code WHERE id = v_course_id;
            v_course_updated := v_course_updated + 1;
          ELSE
            INSERT INTO public.courses (code, name, college_id)
            VALUES (v_course_code, v_course_name, v_course_college_id)
            RETURNING id INTO v_course_id;
            v_course_inserted := v_course_inserted + 1;
          END IF;
        END IF;
      ELSE
        -- Without a code, only an uncoded row can be matched. A coded same-name
        -- row makes the identity ambiguous and must not be duplicated.
        SELECT id INTO v_course_id
        FROM public.courses
        WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NULL
        LIMIT 1;

        IF v_course_id IS NOT NULL THEN
          v_course_skipped := v_course_skipped + 1;
        ELSE
          IF EXISTS (
            SELECT 1 FROM public.courses
            WHERE name = v_course_name AND college_id = v_course_college_id AND code IS NOT NULL
          ) THEN
            RAISE EXCEPTION '课程 % 已有编码记录，无编码导入会产生歧义', v_course_name;
          END IF;
          INSERT INTO public.courses (code, name, college_id)
          VALUES (NULL, v_course_name, v_course_college_id)
          RETURNING id INTO v_course_id;
          v_course_inserted := v_course_inserted + 1;
        END IF;
      END IF;

      IF v_term_id IS NULL THEN
        RAISE EXCEPTION '教师 % 有课程但 term 未能建立', v_source_id;
      END IF;
      INSERT INTO public.course_offerings (teacher_id, course_id, term_id)
      VALUES (v_teacher_id, v_course_id, v_term_id)
      ON CONFLICT (teacher_id, course_id, term_id) DO NOTHING;
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_rows = 1 THEN
        v_offering_inserted := v_offering_inserted + 1;
      ELSE
        v_offering_skipped := v_offering_skipped + 1;
      END IF;
    END LOOP;
  END LOOP;

  v_summary := jsonb_build_object(
    'success', true,
    'dryRun', false,
    'dataset', v_dataset,
    'source', v_source,
    'checksum', p_checksum,
    'term', jsonb_build_object(
      'inserted', v_term_inserted,
      'updated', v_term_updated,
      'skipped', v_term_skipped
    ),
    'teachers', jsonb_build_object(
      'inserted', v_teacher_inserted,
      'updated', v_teacher_updated,
      'skipped', v_teacher_skipped
    ),
    'courses', jsonb_build_object(
      'inserted', v_course_inserted,
      'updated', v_course_updated,
      'skipped', v_course_skipped
    ),
    'offerings', jsonb_build_object(
      'inserted', v_offering_inserted,
      'skipped', v_offering_skipped
    )
  );

  INSERT INTO public.import_batches (dataset, source, checksum, summary)
  VALUES (v_dataset, v_source, p_checksum, v_summary);

  RETURN v_summary;
END $$;
REVOKE ALL ON FUNCTION private.upc_import_dataset_apply(JSONB, TEXT)
  FROM PUBLIC, anon, authenticated;

-- Dry run uses the same apply function in a subtransaction, then raises a private
-- sentinel to force a rollback. Other errors propagate unchanged, so a preflight
-- cannot report success for a batch that the real import would reject.
CREATE OR REPLACE FUNCTION public.import_upc_dataset(
  p_payload JSONB,
  p_checksum TEXT,
  p_dry_run BOOLEAN DEFAULT false
) RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_summary JSONB;
  v_detail TEXT;
BEGIN
  IF p_dry_run IS NOT TRUE THEN
    RETURN private.upc_import_dataset_apply(p_payload, p_checksum);
  END IF;

  BEGIN
    v_summary := private.upc_import_dataset_apply(p_payload, p_checksum);
    RAISE EXCEPTION USING ERRCODE = 'UP001', MESSAGE = 'UPC_DRY_RUN',
      DETAIL = (v_summary || jsonb_build_object('dryRun', true))::text;
  EXCEPTION WHEN SQLSTATE 'UP001' THEN
    GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
    RETURN v_detail::jsonb;
  END;
END $$;

REVOKE ALL ON FUNCTION public.import_upc_dataset(JSONB, TEXT, BOOLEAN)
  FROM PUBLIC, anon, authenticated;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION public.import_upc_dataset(JSONB, TEXT, BOOLEAN) TO service_role;
  END IF;
END $$;

NOTIFY pgrst, 'reload schema';


COMMIT;
